"""Strict request parsing and schema validation for the version3 contract."""
import json

MAX_BYTES = 16 * 1024 * 1024
MAX_DEPTH = 64
MAX_CASES = 8
MAX_TOTAL_WINDOWS = 1024

CASE_KEYS = ('model', 'class_values', 'stats', 'bucket', 'slots', 'flows',
             'groups', 'windows')


class Invalid(Exception):
    """Raised for every rejected request."""


def _pairs(items):
    out = {}
    for key, value in items:
        if key in out:
            raise Invalid('duplicate key')
        out[key] = value
    return out


def _no_float(text):
    raise Invalid('non integer number')


def _no_constant(text):
    raise Invalid('nonfinite number')


def parse(raw):
    if raw is None:
        raise Invalid('no input')
    if len(raw) > MAX_BYTES:
        raise Invalid('oversized')
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise Invalid('bad utf-8')
    try:
        return json.loads(text, object_pairs_hook=_pairs, parse_float=_no_float,
                          parse_constant=_no_constant)
    except Invalid:
        raise
    except RecursionError:
        raise Invalid('too deep')
    except ValueError:
        raise Invalid('bad json')


def _depth(value, limit=MAX_DEPTH):
    """Iterative container nesting depth; raises when over the limit."""
    stack = [(value, 1)]
    best = 0
    while stack:
        node, level = stack.pop()
        if level > limit:
            raise Invalid('depth over limit')
        if level > best:
            best = level
        if type(node) is dict:
            for v in node.values():
                if type(v) is dict or type(v) is list:
                    stack.append((v, level + 1))
        elif type(node) is list:
            for v in node:
                if type(v) is dict or type(v) is list:
                    stack.append((v, level + 1))
    return best


def _int(value):
    return type(value) is int


def _row(value, width):
    if type(value) is not list or len(value) != width:
        raise Invalid('bad row width')
    for item in value:
        if not _int(item):
            raise Invalid('bad row scalar')
    return value


def _rng(value, low, high):
    if not _int(value) or value < low or value > high:
        raise Invalid('out of range')
    return value


def _validate_case(case, window_budget):
    if type(case) is not dict:
        raise Invalid('case not object')
    keys = set(case)
    if keys != set(CASE_KEYS):
        raise Invalid('case keys')
    model = case['model']
    if type(model) is not str or model not in ('cnn', 'rnn'):
        raise Invalid('model')
    values = case['class_values']
    if type(values) is not list or len(values) != 7:
        raise Invalid('class_values length')
    for item in values:
        _rng(item, 1, 1000)
    stats = _row(case['stats'], 3)
    for item in stats:
        _rng(item, 1, 10 ** 9)
    bucket = _row(case['bucket'], 2)
    _rng(bucket[0], 1, 512)
    _rng(bucket[1], 0, bucket[0])
    slots = case['slots']
    if type(slots) is not list or not (1 <= len(slots) <= 256):
        raise Invalid('slots length')
    previous = -1
    for index, slot in enumerate(slots):
        _row(slot, 3)
        _rng(slot[0], 0, 10 ** 12)
        _rng(slot[1], 0, 512)
        _rng(slot[2], 0, 512)
        if slot[0] <= previous:
            raise Invalid('slot times not increasing')
        previous = slot[0]
        if index == 0 and slot[2] != 0:
            raise Invalid('first refill must be zero')
    groups = case['groups']
    if type(groups) is not list or len(groups) > 32:
        raise Invalid('groups length')
    gcount = len(groups)
    for group in groups:
        _row(group, 2)
        if group[0] != -1:
            _rng(group[0], 0, gcount - 1)
        _rng(group[1], 0, 512)
    if gcount:
        state = [0] * gcount
        for start in range(gcount):
            if state[start]:
                continue
            node = start
            seen = []
            while node != -1 and state[node] == 0:
                state[node] = 1
                seen.append(node)
                node = groups[node][0]
            if node != -1 and state[node] == 1:
                raise Invalid('group cycle')
            for item in seen:
                state[item] = 2
    flows = case['flows']
    if type(flows) is not list or not (1 <= len(flows) <= 32):
        raise Invalid('flows length')
    for flow in flows:
        _row(flow, 4)
        target = _rng(flow[0], 1, 64)
        _rng(flow[1], target, 512)
        if flow[2] != -1:
            _rng(flow[2], 0, gcount - 1)
        _rng(flow[3], 0, 6)
    windows = case['windows']
    if type(windows) is not list or len(windows) > 512:
        raise Invalid('windows length')
    fcount = len(flows)
    if window_budget[0] + len(windows) > MAX_TOTAL_WINDOWS:
        raise Invalid('too many windows in batch')
    window_budget[0] += len(windows)
    for window in windows:
        if type(window) is not list or len(window) != 8:
            raise Invalid('window width')
        for item in window[:7]:
            if not _int(item):
                raise Invalid('window scalar')
        _rng(window[0], 0, fcount - 1)
        ready = _rng(window[1], 0, 10 ** 12)
        _rng(window[2], ready, 10 ** 12)
        _rng(window[3], 1, 65535)
        _rng(window[4], 1, 320)
        _rng(window[5], 0, 65535)
        _rng(window[6], 1, 1000)
        features = window[7]
        if type(features) is not list or len(features) != 9:
            raise Invalid('feature rows')
        for pair in features:
            _row(pair, 2)
            _rng(pair[0], 0, 1500)
            _rng(pair[1], 0, 2560)


def validate(data):
    if type(data) is not dict:
        raise Invalid('root not object')
    if set(data) != {'version', 'cases'}:
        raise Invalid('root keys')
    if not _int(data['version']) or data['version'] != 3:
        raise Invalid('version')
    cases = data['cases']
    if type(cases) is not list or len(cases) > MAX_CASES:
        raise Invalid('cases')
    _depth(data)
    budget = [0]
    for case in cases:
        _validate_case(case, budget)
    return cases
PYEOF
